package com.example.ledger.store;

import java.util.function.Consumer;

/** One schema change. Ids look like {@code V7__add_account_memo}. */
public interface Migration {
    String id();

    void apply(InMemoryDatabase db);

    static Migration of(String id, Consumer<InMemoryDatabase> change) {
        return new Migration() {
            @Override
            public String id() {
                return id;
            }

            @Override
            public void apply(InMemoryDatabase db) {
                change.accept(db);
            }

            @Override
            public String toString() {
                return id;
            }
        };
    }
}

package com.example.ledger.store;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/** A schema-only stand-in for the ledger database: tables, columns and migration history. */
public final class InMemoryDatabase {
    private final Map<String, Set<String>> tables = new LinkedHashMap<>();
    private final List<String> history = new ArrayList<>();

    public void createTable(String table, String... columns) {
        if (tables.containsKey(table)) {
            throw new IllegalStateException("table " + table + " already exists");
        }
        tables.put(table, new LinkedHashSet<>(List.of(columns)));
    }

    public void addColumn(String table, String column) {
        if (!columnsOf(table).add(column)) {
            throw new IllegalStateException("column " + table + "." + column + " already exists");
        }
    }

    public void dropColumn(String table, String column) {
        if (!columnsOf(table).remove(column)) {
            throw new IllegalStateException("no column " + table + "." + column);
        }
    }

    public boolean hasTable(String table) {
        return tables.containsKey(table);
    }

    public Set<String> tables() {
        return Collections.unmodifiableSet(tables.keySet());
    }

    public Set<String> columns(String table) {
        return Collections.unmodifiableSet(columnsOf(table));
    }

    private Set<String> columnsOf(String table) {
        Set<String> columns = tables.get(table);
        if (columns == null) {
            throw new IllegalStateException("no table " + table);
        }
        return columns;
    }

    /** Ids of the migrations applied so far, in the order they ran. */
    public List<String> history() {
        return Collections.unmodifiableList(history);
    }

    public void recordApplied(String migrationId) {
        history.add(migrationId);
    }
}

package com.example.ledger.store;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Applies schema migrations in version order.
 *
 * <p>Ids look like {@code V7__add_account_memo}: "V", the version number, two
 * underscores and a description. Versions are numbers (V10 comes after V9) and must be
 * unique. A database's history lists the ids applied so far; the migrations with a
 * higher version than the latest applied one are pending.
 */
public final class SchemaMigrator {
    private static final Pattern ID = Pattern.compile("V(\\d+)__[a-z0-9_]+");

    private final List<Migration> migrations;

    public SchemaMigrator(List<Migration> migrations) {
        Set<String> seen = new HashSet<>();
        for (Migration migration : migrations) {
            version(migration.id());
            if (!seen.add(migration.id())) {
                throw new IllegalArgumentException("duplicate migration " + migration.id());
            }
        }
        this.migrations = List.copyOf(migrations);
    }

    /** Version number of a migration id: {@code version("V12__x") == 12}. */
    public static int version(String id) {
        Matcher matcher = ID.matcher(id);
        if (!matcher.matches()) {
            throw new IllegalArgumentException("invalid migration id: " + id);
        }
        return Integer.parseInt(matcher.group(1));
    }

    /** Ids still to apply, in the order they will run. */
    public List<String> pending(InMemoryDatabase db) {
        List<String> applied = db.history();
        String latest = applied.isEmpty() ? null : applied.get(applied.size() - 1);
        List<String> ids = new ArrayList<>();
        for (Migration migration : migrations) {
            ids.add(migration.id());
        }
        Collections.sort(ids);
        List<String> pending = new ArrayList<>();
        for (String id : ids) {
            if (latest == null || id.compareTo(latest) > 0) {
                pending.add(id);
            }
        }
        return pending;
    }

    /** Applies every pending migration, recording each one, and returns the ids that ran. */
    public List<String> migrate(InMemoryDatabase db) {
        Map<String, Migration> byId = new HashMap<>();
        for (Migration migration : migrations) {
            byId.put(migration.id(), migration);
        }
        List<String> ran = new ArrayList<>();
        for (String id : pending(db)) {
            byId.get(id).apply(db);
            db.recordApplied(id);
            ran.add(id);
        }
        return ran;
    }
}

package com.example.ledger.store;

import java.util.List;

/** The ledger's database schema, as an ordered set of migrations. */
public final class LedgerSchema {
    private LedgerSchema() {
    }

    public static List<Migration> migrations() {
        return List.of(
                Migration.of("V1__create_accounts", db -> db.createTable("accounts", "id", "name", "type", "currency")),
                Migration.of("V2__create_transactions", db -> db.createTable("transactions", "id", "date", "description")),
                Migration.of("V3__create_entries", db -> db.createTable("entries", "transaction_id", "account_id", "amount_minor")),
                Migration.of("V4__add_account_frozen", db -> db.addColumn("accounts", "frozen")),
                Migration.of("V5__add_account_overdraft", db -> db.addColumn("accounts", "allow_overdraft")),
                Migration.of("V6__add_entry_currency", db -> db.addColumn("entries", "currency")),
                Migration.of("V7__create_periods", db -> db.createTable("periods", "month")),
                Migration.of("V8__add_period_closed_at", db -> db.addColumn("periods", "closed_at")),
                Migration.of("V9__create_audit_log", db -> db.createTable("audit_log", "at", "action")),
                Migration.of("V10__add_audit_actor", db -> db.addColumn("audit_log", "actor")),
                Migration.of("V11__add_transaction_reversal_of", db -> db.addColumn("transactions", "reversal_of")),
                Migration.of("V12__drop_audit_action", db -> db.dropColumn("audit_log", "action")));
    }
}

